import React from 'react';
import ComputerImage from '../images/computer2-1.png';
import BirdBooks from '../images/bird-books.png';
import ContactImage from '../images/contact-image.png';
import GirlBooks from '../images/girl-books.png';
import ResumeImage from '../images/resume-writing.png';
import Scheduling from '../images/scheduling.png';
import Review from '../components/Review';
import Contact from '../components/Contact';
import NavBar from '../components/NavBar';
import  { reviews, colors, getRandomColor, sliderSettings } from '../reviews/reviewsData';
import 'tailwindcss/tailwind.css';
/* Custom css in Home.css */
import './Home.css';

import Slider from 'react-slick';
import "slick-carousel/slick/slick.css"; 
import "slick-carousel/slick/slick-theme.css";

const Home: React.FC = () => {
  /*const reviews = [
    { idx: 1, reviewer: 'John Doe', lessons: '5', quote: 'Great tutor!' },
    { idx: 2, reviewer: 'Jane Smith', lessons: '10', quote: 'Highly recommend!' },
  ];*/

  return (
    <div style={{ minHeight: '100vh'}} className="border-b-4 border-black">
      <section className="mt-0 space-y-8">
          <div className="flex flex-col md:flex-row items-center space-y-4 md:space-y-0 bg-customPurple border-t-2 border-b-2 border-black">
            <img src={ComputerImage} alt="Olivertutor.me" className="w-full md:w-1/2 border-r-2 md:border-r-2 border-black" />
            <div className="p-4 space-y-4 ">
              <h1 className="text-4xl font-bold">Enhance Your Career With Confidence</h1>
              <p>
                Join me on this exciting journey into AI and Python. Let's not just learn,
                but innovate, explore, and lead the future together.
              </p>
              <button className="bg-blue-600 text-white px-4 py-2 rounded-md">Book Tutoring</button>
            </div>
          </div>
      </section>

      {/* Reviews Section */}
      {/*<section className="space-y-4 bg-white shadow-lg rounded-lg p-6">
          <h2 className="text-2xl font-bold text-blue-600">Reviews</h2>
          <div className="space-y-4">
          {reviews.map((review, idx) => {
              debugger;
              return (
                <Review 
                  key={idx}
                  reviewer={review.reviewer}
                  lessons={review.lessons}
                  quote={review.quote}
                />
              );
            })}
          </div>
        </section>*/}
        <div className = "bg-white">
        { <section className="space-y-4 bg-white shadow-lg rounded-lg p-6 mt-12 min-h-[400px]">
          {/*<h2 className="text-2xl font-bold text-blue-600">Reviews</h2>*/}
          <Slider {...sliderSettings}>
            {reviews.map((review, idx) => (
              <div key={idx} className="p-2">
                <Review 
                  reviewer={review.reviewer}
                  lessons={review.lessons}
                  quote={review.quote}
                  backgroundColor={colors[idx % colors.length]}
                />
              </div>
            ))}
          </Slider>
        </section>}
        </div>

      <section className="bg-customGreen mt-0 flex flex-col md:flex-row items-center space-y-4 md:space-y-0 border-t-2 border-b-2 border-black min-h-[400px]">
        <div className="w-1/2 mx-auto">
          <div className="flex-1 space-y-4 p-4">
            <h2 className="text-4xl font-bold">About Oliver</h2>
            <p>Hi, I'm Oliver! I am here to guide you through the fascinating fields of Data Science, including the latest in AI and Python development. As a senior Biology student, I started the journey into AI and programming from scratch. I know how daunting and intimidating these complex topics can be.</p>
          </div>
        </div>
      </section>

      <section className="mt-0 space-y-8">
        <div className="relative bg-customPurple mt-0 flex flex-col md:flex-row items-center space-y-4 md:space-y-0 section-border">
          <img src={ResumeImage} alt="Oliver's Resume" className="w-full md:w-1/2" />
          <div className="flex-1 space-y-4 p-4">
            <h2 className="text-2xl font-bold">Checkout Oliver's Resume</h2>
            <button className="bg-customBtn text-black px-4 py-2 rounded-md">Resume</button>
          </div>
        </div>
      </section>

      <section className="mt-0 space-y-8 border-t-2 border-b-2 border-black">
        <div className="bg-customGreen mt-0 flex flex-col md:flex-row items-center space-y-4 md:space-y-0">
          <div className="flex-1 space-y-4 p-4">
            <h2 className="text-2xl font-bold">Portfolio</h2>
            <button className="bg-customBtn text-black px-4 py-2 rounded-md">Portfolio Coming Soon</button>
          </div>
          <img src={BirdBooks} alt="Portfolio" className="w-full md:w-1/2 border-l-2 md:border-l-2 border-black" />
        </div>
      </section>

      <div className="relative bg-customPink mt-0 flex flex-col md:flex-row items-center space-y-4 md:space-y-0 section-border">
        <img src={GirlBooks} alt="Blog" className="w-full md:w-1/2" />
        <div className="flex-1 space-y-4 p-4">
          <h2 className="text-2xl font-bold">Blog</h2>
          <button className="bg-customBtn text-black px-4 py-2 rounded-md">Blog Coming Soon</button>
        </div>
      </div>

      <div className="bg-customGreen flex mt-0 flex-col md:flex-row items-center space-y-4 md:space-y-0 border-t-2 border-b-2 border-black">
        <div className="flex-1 space-y-4 p-4">
          <h2 className="text-2xl font-bold">Schedule a Session</h2>
          <button className="bg-customBtn text-black px-4 py-2 rounded-md">Book Tutoring</button>
        </div>
        <img src={Scheduling} alt="Scheduling" className="w-full md:w-1/2 border-l-2 md:border-l-2 border-black" />
      </div>

      <section className="bg-customGreen mt-0 flex flex-col md:flex-row items-center space-y-4 md:space-y-0 border-b-2 border-black">
        <img src={ContactImage} alt="Blog" className="w-full md:w-1/2" />
        <div className="flex-1 space-y-4 p-4">
          <Contact />
        </div>
      </section>
    </div>
  );
};

export default Home;
